class Solution {
  private static int lower(int[] a, long x) {
    int lo = 0, hi = a.length;
    while (lo < hi) {
      int mid = (lo + hi) >>> 1;
      if (a[mid] < x) lo = mid + 1;
      else hi = mid;
    }
    return lo;
  }

  public int maxFrequency(int[] nums, int k, int numOperations) {
    java.util.Arrays.sort(nums);
    int n = nums.length, ans = 0;
    for (int i = 0; i < n; ) {
      int j = i;
      while (j < n && nums[j] == nums[i]) j++;
      int eq = j - i;
      int c = lower(nums, (long) nums[i] + k + 1) - lower(nums, (long) nums[i] - k);
      ans = Math.max(ans, eq + Math.min(numOperations, c - eq));
      i = j;
    }
    for (int l = 0, r = 0; r < n; r++) {
      while ((long) nums[r] - nums[l] > 2L * k) l++;
      ans = Math.max(ans, Math.min(numOperations, r - l + 1));
    }
    return ans;
  }
}
